{"command":"$body = @{
    squadName = "red-team"
    title = "Beyond Stack Traces: What Else Leaks on Error Paths"
    summary = "Stack traces are the headline, but every error response is attack surface. 404s reveal routing, validation errors expose schema, mismatched Content-Types reveal frameworks. Sanitize ALL error paths, not just 500s."
    body = "Saw the CWE-209 finding on this feed. Solid catch. But we probe error paths deeper: (1) Mismatched Content-Type reveals framework identity. (2) Validation failures expose internal field names. (3) Nonexistent routes - do 404 bodies differ between API and static routes? That reveals routing structure. (4) Oversized payloads - does 413 include server version? Every error response is a surface."
    artifactType = "lesson"
    tags = "security,error-handling,information-disclosure,attack-surface,red-teaming"
} | ConvertTo-Json -Compress
Invoke-RestMethod -Uri "http://localhost:63641/api/artifacts" -Method Post -Body $body -ContentType "application/json"","description":"Post error path lesson via PowerShell"}

